import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import confetti from 'canvas-confetti';
import clsx from 'clsx';
import { VoxelGame, GameOptions, HudState, GameResult } from './game/engine';
import { sfx } from './game/audio';
import { Mode, loadSave, getRecord } from './game/survival';
import { Menu, PauseScreen, GameOverScreen } from './components/Screens';
import { HUD } from './components/HUD';
import { TouchControls } from './components/TouchControls';

type Screen = 'menu' | 'playing' | 'paused' | 'over';
interface Toast { id: number; msg: string; tone: string }

export default function App() {
  const hostRef = useRef<HTMLDivElement>(null);
  const gameRef = useRef<VoxelGame | null>(null);
  const [screen, setScreen] = useState<Screen>('menu');
  const [run, setRun] = useState<GameOptions | null>(null);
  const [mode, setMode] = useState<Mode>('survival');
  const [difficulty, setDifficulty] = useState(1);
  const [useSave, setUseSave] = useState(true);
  const [hasSave, setHasSave] = useState({ survival: false, creative: false });
  const [record, setRecord] = useState(0);
  const [hud, setHud] = useState<HudState | null>(null);
  const [result, setResult] = useState<GameResult | null>(null);
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [muted, setMuted] = useState(false);
  const screenRef = useRef(screen); screenRef.current = screen;
  const isTouch = useMemo(() => typeof window !== 'undefined' && ('ontouchstart' in window || navigator.maxTouchPoints > 0), []);

  const refreshMeta = useCallback(() => {
    setRecord(getRecord());
    setHasSave({ survival: !!loadSave('survival'), creative: !!loadSave('creative') });
  }, []);
  useEffect(() => { refreshMeta(); }, [refreshMeta]);

  const pushToast = useCallback((msg: string, tone: string) => {
    const id = Date.now() + Math.random();
    setToasts(t => [...t.slice(-2), { id, msg, tone }]);
    window.setTimeout(() => setToasts(t => t.filter(x => x.id !== id)), 3000);
    if (tone === 'level') confetti({ particleCount: 90, spread: 80, origin: { y: 0.25 }, colors: ['#a3e635', '#fbbf24', '#22d3ee', '#ffffff'] });
  }, []);

  // Motor: en el menú corre un mundo de demostración; al jugar se crea la partida real.
  useEffect(() => {
    const host = hostRef.current; if (!host) return;
    const opts: GameOptions = run || { mode: 'creative', difficulty: 1, useSave: false, demo: true };
    const g = new VoxelGame(host, opts, {
      onHud: setHud,
      onPause: () => { if (screenRef.current === 'playing') setScreen('paused'); },
      onGameOver: r => {
        setResult(r); setScreen('over'); setRecord(r.record);
        if (r.newRecord) confetti({ particleCount: 160, spread: 100, origin: { y: 0.4 } });
      },
      onToast: pushToast,
    });
    gameRef.current = g;
    return () => { g.dispose(); gameRef.current = null; };
  }, [run, pushToast]);

  useEffect(() => { gameRef.current?.setPaused(screen === 'paused' || screen === 'over'); }, [screen, run]);

  // Esc / P para reanudar desde la pausa
  useEffect(() => {
    if (screen !== 'paused') return;
    const h = (e: KeyboardEvent) => { if (e.code === 'Escape' || e.code === 'KeyP') resume(); };
    window.addEventListener('keydown', h); return () => window.removeEventListener('keydown', h);
  });

  const lockSoon = () => window.setTimeout(() => gameRef.current?.lock(), 60);
  const play = () => {
    sfx.init(); setHud(null); setResult(null);
    setRun({ mode, difficulty, useSave: useSave && hasSave[mode] });
    setScreen('playing'); lockSoon();
  };
  const resume = () => { sfx.init(); setScreen('playing'); gameRef.current?.lock(); };
  const restart = () => { if (!run) return; setHud(null); setResult(null); setRun({ ...run, useSave: false }); setScreen('playing'); lockSoon(); };
  const toMenu = () => { setRun(null); setScreen('menu'); setHud(null); window.setTimeout(refreshMeta, 120); };
  const toggleMute = () => { const m = !muted; setMuted(m); sfx.setMuted(m); };

  return (
    <div className="relative w-full h-screen overflow-hidden bg-[#0a0f24] select-none text-white">
      <div ref={hostRef} className="absolute inset-0" />

      {screen === 'menu' && (
        <Menu mode={mode} setMode={setMode} difficulty={difficulty} setDifficulty={setDifficulty} record={record}
          hasSave={hasSave[mode]} useSave={useSave} setUseSave={setUseSave} onPlay={play} muted={muted} onMute={toggleMute} />
      )}
      {(screen === 'playing' || screen === 'paused') && hud && (
        <HUD hud={hud} muted={muted} isTouch={isTouch} onMute={toggleMute} onPause={() => setScreen('paused')}
          onSlot={i => gameRef.current?.selectSlot(i)} onLock={() => gameRef.current?.lock()} />
      )}
      {screen === 'playing' && isTouch && <TouchControls getGame={() => gameRef.current} creative={run?.mode === 'creative'} />}
      {screen === 'paused' && <PauseScreen objective={hud?.objective || null} onResume={resume} onRestart={restart} onMenu={toMenu} />}
      {screen === 'over' && result && <GameOverScreen r={result} onRetry={restart} onMenu={toMenu} />}

      <div className="absolute top-20 left-1/2 -translate-x-1/2 flex flex-col items-center gap-2 pointer-events-none">
        {toasts.map(t => (
          <div key={t.id} className={clsx('px-4 py-2 rounded-lg text-sm font-bold border-b-4 shadow-lg animate-[pulse_1.2s_ease-in-out_1]',
            t.tone === 'bad' ? 'bg-red-600/90 border-red-900' : t.tone === 'level' ? 'bg-amber-400 text-amber-950 border-amber-700' : t.tone === 'good' ? 'bg-lime-500/90 text-lime-950 border-lime-800' : 'bg-slate-800/90 border-slate-950')}
            style={{ fontFamily: 'ui-monospace, Menlo, Consolas, monospace' }}>
            {t.msg}
          </div>
        ))}
      </div>
    </div>
  );
}

import { useMemo } from 'react';
import { Heart, Moon, Pause, Sun, Target, Volume2, VolumeX, Zap, Trophy, Feather } from 'lucide-react';
import clsx from 'clsx';
import { HudState } from '../game/engine';
import { HOTBAR, BLOCKS, blockIcon } from '../game/blocks';

interface Props {
  hud: HudState; muted: boolean; isTouch: boolean;
  onMute: () => void; onPause: () => void; onSlot: (i: number) => void; onLock: () => void;
}

const MONO = { fontFamily: 'ui-monospace, SFMono-Regular, Menlo, Consolas, monospace' };
const panel = 'bg-slate-950/55 backdrop-blur-md border border-white/10 shadow-[0_4px_0_rgba(0,0,0,0.35)] rounded-lg';

function Hearts({ hp, max }: { hp: number; max: number }) {
  const n = Math.ceil(max / 2);
  return (
    <div className="flex gap-0.5">
      {Array.from({ length: n }, (_, i) => {
        const v = hp - i * 2;
        return (
          <div key={i} className="relative w-5 h-5">
            <Heart className="absolute inset-0 w-5 h-5 text-black/50" fill="rgba(0,0,0,0.45)" strokeWidth={2.5} />
            {v > 0 && (
              <div className="absolute inset-0 overflow-hidden" style={{ width: v >= 2 ? '100%' : '50%' }}>
                <Heart className={clsx('w-5 h-5 text-red-500', hp <= 6 && 'animate-pulse')} fill="#ef4444" strokeWidth={2.5} />
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

export function HUD({ hud, muted, isTouch, onMute, onPause, onSlot, onLock }: Props) {
  const icons = useMemo(() => HOTBAR.map(id => blockIcon(id)), []);
  const survival = hud.mode === 'survival';
  const obj = hud.objective;
  const ring = 2 * Math.PI * 14;
  return (
    <div className="absolute inset-0 pointer-events-none text-white" style={MONO}>
      {/* Daño y noche */}
      <div className="absolute inset-0 transition-opacity duration-150" style={{ opacity: hud.hurt, background: 'radial-gradient(ellipse at center, transparent 45%, rgba(220,30,30,0.55) 100%)' }} />
      {hud.night && <div className="absolute inset-0" style={{ background: 'radial-gradient(ellipse at center, transparent 55%, rgba(5,10,40,0.45) 100%)' }} />}

      {/* Arriba izquierda: estado */}
      <div className={clsx(panel, 'absolute top-3 left-3 px-3 py-2 space-y-1.5')}>
        {survival ? (
          <>
            <Hearts hp={hud.health} max={hud.maxHealth} />
            <div className="flex items-center gap-3 text-sm">
              <span className="flex items-center gap-1 text-amber-300 font-bold"><Trophy className="w-4 h-4" />{hud.score.toLocaleString('es')}</span>
              <span className="text-lime-300 font-bold">NIVEL {hud.level}</span>
            </div>
          </>
        ) : (
          <div className="text-sm font-bold text-sky-300 flex items-center gap-2">
            MODO CREATIVO {hud.flying && <span className="flex items-center gap-1 text-amber-300"><Feather className="w-4 h-4" />volando</span>}
          </div>
        )}
        {hud.boost > 0 && (
          <div className="flex items-center gap-1 text-xs text-cyan-300 font-bold"><Zap className="w-4 h-4" fill="currentColor" />Minería veloz {Math.ceil(hud.boost)}s</div>
        )}
      </div>

      {/* Arriba centro: objetivo */}
      {obj && (
        <div className={clsx(panel, 'absolute top-3 left-1/2 -translate-x-1/2 px-4 py-2 w-[min(360px,60vw)] hidden sm:block')}>
          <div className="flex items-center gap-2 text-xs uppercase tracking-wider text-lime-300"><Target className="w-4 h-4" />Objetivo</div>
          <div className="text-sm font-bold mt-0.5 truncate">{obj.label}</div>
          <div className="mt-1.5 h-2 bg-black/50 rounded-sm overflow-hidden">
            <div className="h-full bg-gradient-to-r from-lime-400 to-emerald-500 transition-all" style={{ width: `${Math.min(100, (obj.have / obj.need) * 100)}%` }} />
          </div>
          <div className="text-[10px] text-white/60 mt-0.5 text-right">{obj.have} / {obj.need}</div>
        </div>
      )}

      {/* Arriba derecha: reloj y botones */}
      <div className="absolute top-3 right-3 flex items-center gap-2 pointer-events-auto">
        <div className={clsx(panel, 'px-3 py-2 flex items-center gap-2 text-sm font-bold')}>
          {hud.night ? <Moon className="w-4 h-4 text-indigo-300" /> : <Sun className="w-4 h-4 text-amber-300" />}
          <span>Día {hud.days}</span><span className="text-white/60">{hud.clock}</span>
        </div>
        <button onClick={onMute} className={clsx(panel, 'p-2 hover:bg-white/10')} aria-label="Silenciar">{muted ? <VolumeX className="w-5 h-5" /> : <Volume2 className="w-5 h-5" />}</button>
        <button onClick={onPause} className={clsx(panel, 'p-2 hover:bg-white/10')} aria-label="Pausa"><Pause className="w-5 h-5" /></button>
      </div>

      {/* Mira y progreso de minado */}
      <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2">
        <div className="relative w-9 h-9 flex items-center justify-center">
          <div className="absolute w-[2px] h-5 bg-white/90 mix-blend-difference" />
          <div className="absolute h-[2px] w-5 bg-white/90 mix-blend-difference" />
          {hud.mining > 0 && (
            <svg className="absolute inset-0 -rotate-90" viewBox="0 0 36 36">
              <circle cx="18" cy="18" r="14" fill="none" stroke="rgba(0,0,0,0.4)" strokeWidth="3" />
              <circle cx="18" cy="18" r="14" fill="none" stroke="#a3e635" strokeWidth="3" strokeDasharray={`${ring * hud.mining} ${ring}`} />
            </svg>
          )}
        </div>
        {hud.target && <div className="absolute top-10 left-1/2 -translate-x-1/2 text-[11px] text-white/70 whitespace-nowrap drop-shadow">{hud.target}</div>}
      </div>

      {!hud.locked && !isTouch && (
        <button onClick={onLock} className="pointer-events-auto absolute left-1/2 top-[62%] -translate-x-1/2 px-4 py-2 rounded-md bg-black/60 border border-white/20 text-sm hover:bg-black/70">
          Haz clic para controlar la cámara
        </button>
      )}

      {/* Barra rápida */}
      <div className={clsx('absolute left-1/2 -translate-x-1/2 flex gap-1 p-1.5 pointer-events-auto', panel, isTouch ? 'bottom-2 scale-90' : 'bottom-3')}>
        {HOTBAR.map((id, i) => {
          const c = hud.counts[i], sel = hud.slot === i, empty = c === 0;
          return (
            <button key={id} onClick={() => onSlot(i)} title={BLOCKS[id].name}
              className={clsx('relative w-11 h-11 sm:w-12 sm:h-12 rounded flex items-center justify-center transition-transform',
                sel ? 'bg-white/20 ring-2 ring-amber-300 -translate-y-1' : 'bg-black/30 hover:bg-white/10')}>
              <img src={icons[i]} alt={BLOCKS[id].name} className={clsx('w-9 h-9', empty && 'opacity-40')} style={{ imageRendering: 'pixelated' }} draggable={false} />
              <span className="absolute top-0 left-1 text-[9px] text-white/50">{i + 1}</span>
              {c >= 0 && <span className="absolute bottom-0 right-1 text-[11px] font-bold drop-shadow-[0_1px_0_#000]">{c}</span>}
            </button>
          );
        })}
      </div>
      <div className="absolute left-1/2 -translate-x-1/2 bottom-[74px] text-xs font-bold text-amber-200 drop-shadow-[0_1px_0_#000] hidden sm:block">{BLOCKS[HOTBAR[hud.slot]].name}</div>
    </div>
  );
}

import { ReactNode, useMemo } from 'react';
import { Swords, Hammer, Trophy, Play, RotateCcw, Home, Volume2, VolumeX, Skull, Sparkles, Mouse, Keyboard, Target } from 'lucide-react';
import clsx from 'clsx';
import { Mode, DIFFICULTIES, Objective } from '../game/survival';
import { GameResult } from '../game/engine';
import { blockIcon, GRASS, LOG, CRYSTAL, LAMP, BRICK } from '../game/blocks';

const MONO = { fontFamily: 'ui-monospace, SFMono-Regular, Menlo, Consolas, monospace' };
const card = 'bg-slate-950/70 backdrop-blur-md border border-white/10 rounded-xl shadow-[0_6px_0_rgba(0,0,0,0.4)]';

function Title({ small }: { small?: boolean }) {
  const sh = '0 3px 0 #365314, 0 6px 0 #1a2e05, 0 10px 24px rgba(0,0,0,0.6)';
  const sh2 = '0 3px 0 #92400e, 0 6px 0 #451a03, 0 10px 24px rgba(0,0,0,0.6)';
  return (
    <h1 className={clsx('font-black leading-none tracking-tight', small ? 'text-4xl' : 'text-6xl sm:text-7xl')} style={MONO}>
      <span style={{ color: '#a3e635', textShadow: sh }}>VOXEL</span>
      <span style={{ color: '#fbbf24', textShadow: sh2 }}>CRAFT</span>
    </h1>
  );
}

export function BlockButton({ onClick, children, tone = 'green', className }: { onClick: () => void; children: ReactNode; tone?: 'green' | 'slate' | 'amber'; className?: string }) {
  const tones = {
    green: 'bg-lime-500 hover:bg-lime-400 border-lime-800 text-lime-950',
    amber: 'bg-amber-400 hover:bg-amber-300 border-amber-700 text-amber-950',
    slate: 'bg-slate-700 hover:bg-slate-600 border-slate-900 text-white',
  };
  return (
    <button onClick={onClick} style={MONO}
      className={clsx('flex items-center justify-center gap-2 px-5 py-3 rounded-lg font-black uppercase tracking-wider border-b-[5px] active:border-b-2 active:translate-y-[3px] transition-all', tones[tone], className)}>
      {children}
    </button>
  );
}

interface MenuProps {
  mode: Mode; setMode: (m: Mode) => void; difficulty: number; setDifficulty: (d: number) => void;
  record: number; hasSave: boolean; useSave: boolean; setUseSave: (v: boolean) => void;
  onPlay: () => void; muted: boolean; onMute: () => void;
}

export function Menu(p: MenuProps) {
  const icons = useMemo(() => [GRASS, LOG, CRYSTAL, BRICK, LAMP].map(blockIcon), []);
  const modes: { id: Mode; label: string; icon: ReactNode; desc: string }[] = [
    { id: 'survival', label: 'Supervivencia', icon: <Swords className="w-5 h-5" />, desc: 'Recolecta, cumple objetivos y resiste a las criaturas de la noche.' },
    { id: 'creative', label: 'Creativo', icon: <Hammer className="w-5 h-5" />, desc: 'Bloques infinitos, vuelo libre y sin peligros. ¡Solo construye!' },
  ];
  return (
    <div className="absolute inset-0 overflow-y-auto text-white" style={{ background: 'linear-gradient(90deg, rgba(6,10,28,0.92) 0%, rgba(6,10,28,0.7) 40%, rgba(6,10,28,0) 75%)' }}>
      <button onClick={p.onMute} className="absolute top-4 right-4 p-2 rounded-lg bg-black/40 border border-white/15 hover:bg-black/60" aria-label="Silenciar">
        {p.muted ? <VolumeX className="w-5 h-5" /> : <Volume2 className="w-5 h-5" />}
      </button>
      <div className="min-h-full flex flex-col justify-center px-6 sm:px-12 py-8 max-w-xl">
        <div className="flex gap-1.5 mb-4">
          {icons.map((s, i) => <img key={i} src={s} className="w-9 h-9" style={{ imageRendering: 'pixelated', transform: `translateY(${i % 2 ? 4 : 0}px)` }} alt="" />)}
        </div>
        <Title />
        <p className="mt-4 text-white/80 text-base sm:text-lg max-w-md">
          Un mundo infinito de cubos te espera. Excava montañas, tala bosques, levanta tu refugio antes de que caiga la noche.
        </p>

        <div className="mt-6 grid grid-cols-2 gap-3">
          {modes.map(m => (
            <button key={m.id} onClick={() => p.setMode(m.id)}
              className={clsx('text-left p-3 rounded-xl border-2 transition', p.mode === m.id ? 'border-amber-300 bg-amber-300/15' : 'border-white/10 bg-black/30 hover:border-white/30')}>
              <div className="flex items-center gap-2 font-black uppercase text-sm" style={MONO}>{m.icon}{m.label}</div>
              <div className="text-xs text-white/65 mt-1 leading-snug">{m.desc}</div>
            </button>
          ))}
        </div>

        <div className={clsx('mt-4 transition-opacity', p.mode === 'creative' && 'opacity-40 pointer-events-none')}>
          <div className="text-xs uppercase tracking-widest text-white/50 mb-1.5" style={MONO}>Dificultad</div>
          <div className="flex gap-2">
            {DIFFICULTIES.map((d, i) => (
              <button key={d.name} onClick={() => p.setDifficulty(i)}
                className={clsx('flex-1 py-2 rounded-lg text-sm font-bold border-2 transition', p.difficulty === i ? 'border-lime-400 bg-lime-400/15 text-lime-200' : 'border-white/10 bg-black/30 hover:border-white/30')}>
                {d.name}
              </button>
            ))}
          </div>
        </div>

        {p.hasSave && (
          <label className="mt-4 flex items-center gap-2 text-sm cursor-pointer">
            <input type="checkbox" checked={p.useSave} onChange={e => p.setUseSave(e.target.checked)} className="w-4 h-4 accent-lime-400" />
            Continuar mi mundo guardado
          </label>
        )}

        <div className="mt-6 flex items-center gap-4">
          <BlockButton onClick={p.onPlay} className="text-xl px-10 py-4"><Play className="w-6 h-6" fill="currentColor" />Jugar</BlockButton>
          <div className="flex items-center gap-2 text-amber-300" style={MONO}>
            <Trophy className="w-5 h-5" />
            <div><div className="text-[10px] uppercase text-white/50">Récord</div><div className="font-black text-lg leading-none">{p.record.toLocaleString('es')}</div></div>
          </div>
        </div>

        <div className={clsx(card, 'mt-8 p-4 text-xs text-white/75 grid grid-cols-2 gap-x-4 gap-y-1.5')}>
          <div className="col-span-2 flex items-center gap-2 text-white font-bold mb-1"><Keyboard className="w-4 h-4" />Controles<Mouse className="w-4 h-4 ml-2" /></div>
          <span><b className="text-amber-200">WASD / ↑↓</b> moverse</span><span><b className="text-amber-200">← →</b> girar</span>
          <span><b className="text-amber-200">Ratón</b> mirar</span><span><b className="text-amber-200">Espacio</b> saltar</span>
          <span><b className="text-amber-200">Clic izq. / F</b> romper·atacar</span><span><b className="text-amber-200">Clic der. / E</b> colocar</span>
          <span><b className="text-amber-200">1-9 / rueda</b> bloque</span><span><b className="text-amber-200">V</b> volar (creativo)</span>
          <span><b className="text-amber-200">Shift</b> correr</span><span><b className="text-amber-200">Esc / P</b> pausa</span>
        </div>
      </div>
    </div>
  );
}

export function PauseScreen({ objective, onResume, onRestart, onMenu }: { objective: Objective | null; onResume: () => void; onRestart: () => void; onMenu: () => void }) {
  return (
    <div className="absolute inset-0 flex items-center justify-center bg-slate-950/60 backdrop-blur-sm text-white p-4">
      <div className={clsx(card, 'p-6 w-full max-w-sm text-center')}>
        <Title small />
        <div className="mt-2 text-white/60 text-sm uppercase tracking-widest" style={MONO}>Pausa</div>
        {objective && (
          <div className="mt-4 p-3 rounded-lg bg-black/40 text-left text-sm">
            <div className="flex items-center gap-2 text-lime-300 text-xs uppercase"><Target className="w-4 h-4" />Objetivo actual</div>
            <div className="font-bold mt-1">{objective.label} <span className="text-white/50">({objective.have}/{objective.need})</span></div>
          </div>
        )}
        <div className="mt-5 flex flex-col gap-3">
          <BlockButton onClick={onResume}><Play className="w-5 h-5" fill="currentColor" />Continuar</BlockButton>
          <BlockButton onClick={onRestart} tone="amber"><RotateCcw className="w-5 h-5" />Reiniciar</BlockButton>
          <BlockButton onClick={onMenu} tone="slate"><Home className="w-5 h-5" />Menú principal</BlockButton>
        </div>
        <div className="mt-4 text-[11px] text-white/45">El mundo se guarda automáticamente.</div>
      </div>
    </div>
  );
}

export function GameOverScreen({ r, onRetry, onMenu }: { r: GameResult; onRetry: () => void; onMenu: () => void }) {
  const mm = `${Math.floor(r.seconds / 60)}:${String(r.seconds % 60).padStart(2, '0')}`;
  const stats: [string, string | number][] = [['Nivel', r.level], ['Criaturas', r.kills], ['Bloques rotos', r.mined], ['Bloques puestos', r.placed], ['Tiempo', mm], ['Días', r.days]];
  return (
    <div className="absolute inset-0 flex items-center justify-center p-4 text-white" style={{ background: 'radial-gradient(ellipse at center, rgba(60,0,0,0.55), rgba(5,5,15,0.9))' }}>
      <div className={clsx(card, 'p-6 w-full max-w-md text-center')}>
        <Skull className="w-12 h-12 mx-auto text-red-400" />
        <h2 className="mt-2 text-4xl font-black text-red-400" style={{ ...MONO, textShadow: '0 4px 0 #450a0a' }}>HAS CAÍDO</h2>
        <div className="mt-4 text-white/60 text-xs uppercase tracking-widest" style={MONO}>Puntuación</div>
        <div className="text-5xl font-black text-amber-300" style={MONO}>{r.score.toLocaleString('es')}</div>
        {r.newRecord ? (
