}

import { useRef, useState } from 'react';
import { ArrowBigUp, ArrowBigDown, Pickaxe, Box, Feather } from 'lucide-react';
import { VoxelGame } from '../game/engine';

type RPointerEvent<T extends HTMLElement> = { currentTarget: T; pointerId: number; clientX: number; clientY: number; stopPropagation: () => void };
interface Props { getGame: () => VoxelGame | null; creative: boolean }

/** Joystick a la izquierda, arrastre a la derecha para mirar y botones de acción. */
export function TouchControls({ getGame, creative }: Props) {
  const [knob, setKnob] = useState({ x: 0, y: 0 });
  const joyId = useRef<number | null>(null), joyC = useRef({ x: 0, y: 0 });
  const look = useRef<{ id: number; x: number; y: number } | null>(null);
  const R = 52;

  const joyDown = (e: RPointerEvent<HTMLDivElement>) => {
    const r = e.currentTarget.getBoundingClientRect();
    joyId.current = e.pointerId; joyC.current = { x: r.left + r.width / 2, y: r.top + r.height / 2 };
    e.currentTarget.setPointerCapture(e.pointerId); joyMove(e);
  };
  const joyMove = (e: RPointerEvent<HTMLDivElement>) => {
    if (joyId.current !== e.pointerId) return;
    let dx = e.clientX - joyC.current.x, dy = e.clientY - joyC.current.y; const l = Math.hypot(dx, dy);
    if (l > R) { dx = dx / l * R; dy = dy / l * R; }
    setKnob({ x: dx, y: dy });
    const g = getGame(); if (g) { g.input.joyX = dx / R; g.input.joyY = dy / R; }
  };
  const joyUp = () => { joyId.current = null; setKnob({ x: 0, y: 0 }); const g = getGame(); if (g) { g.input.joyX = 0; g.input.joyY = 0; } };

  const lookDown = (e: RPointerEvent<HTMLDivElement>) => { look.current = { id: e.pointerId, x: e.clientX, y: e.clientY }; e.currentTarget.setPointerCapture(e.pointerId); };
  const lookMove = (e: RPointerEvent<HTMLDivElement>) => {
    const l = look.current; if (!l || l.id !== e.pointerId) return;
    const g = getGame(); if (g) { g.input.lookDX += (e.clientX - l.x) * 1.8; g.input.lookDY += (e.clientY - l.y) * 1.8; }
    l.x = e.clientX; l.y = e.clientY;
  };
  const lookUp = () => { look.current = null; };

  const hold = (on: (g: VoxelGame) => void, off?: (g: VoxelGame) => void) => ({
    onPointerDown: (e: RPointerEvent<HTMLButtonElement>) => { e.stopPropagation(); e.currentTarget.setPointerCapture(e.pointerId); const g = getGame(); if (g) on(g); },
    onPointerUp: () => { const g = getGame(); if (g && off) off(g); },
    onPointerCancel: () => { const g = getGame(); if (g && off) off(g); },
  });
  const btn = 'pointer-events-auto w-16 h-16 rounded-full bg-slate-900/55 border-2 border-white/25 backdrop-blur flex flex-col items-center justify-center text-white text-[9px] font-bold active:bg-amber-400/60 active:scale-95 transition';

  return (
    <div className="absolute inset-0 select-none" style={{ touchAction: 'none' }}>
      <div className="absolute right-0 top-16 bottom-24 w-1/2 pointer-events-auto" onPointerDown={lookDown} onPointerMove={lookMove} onPointerUp={lookUp} onPointerCancel={lookUp} />
      <div className="absolute left-6 bottom-24 w-36 h-36 rounded-full bg-slate-900/40 border-2 border-white/20 pointer-events-auto"
        onPointerDown={joyDown} onPointerMove={joyMove} onPointerUp={joyUp} onPointerCancel={joyUp}>
        <div className="absolute left-1/2 top-1/2 w-14 h-14 -ml-7 -mt-7 rounded-full bg-white/70 border-4 border-amber-300 shadow-lg"
          style={{ transform: `translate(${knob.x}px, ${knob.y}px)` }} />
      </div>
      <div className="absolute right-5 bottom-24 grid grid-cols-2 gap-3">
        <button className={btn} {...hold(g => { g.input.breakHeld = true; g.input.breakPressed++; }, g => { g.input.breakHeld = false; })}><Pickaxe className="w-6 h-6" />ROMPER</button>
        <button className={btn} {...hold(g => { g.input.placePressed++; })}><Box className="w-6 h-6" />PONER</button>
        {creative ? (
          <>
            <button className={btn} {...hold(g => { g.input.flyToggle++; })}><Feather className="w-6 h-6" />VOLAR</button>
            <button className={btn} {...hold(g => { g.input.touchDown = true; }, g => { g.input.touchDown = false; })}><ArrowBigDown className="w-6 h-6" />BAJAR</button>
          </>
        ) : <div />}
        <button className={btn + ' col-start-2'} {...hold(g => { g.input.touchJump = true; }, g => { g.input.touchJump = false; })}><ArrowBigUp className="w-7 h-7" />SALTAR</button>
      </div>
    </div>
  );
}

// Audio procedural con Web Audio API: efectos con osciladores/ruido y una música ambiental suave.
class Sfx {
  ctx: AudioContext | null = null;
  private master: GainNode | null = null;
  private musicGain: GainNode | null = null;
  private noiseBuf: AudioBuffer | null = null;
  private musicTimer = 0;
  muted = false;

  init() {
    if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {}); return; }
    try {
      const AC = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
      this.ctx = new AC();
      this.master = this.ctx.createGain(); this.master.gain.value = this.muted ? 0 : 0.55; this.master.connect(this.ctx.destination);
      this.musicGain = this.ctx.createGain(); this.musicGain.gain.value = 0.18; this.musicGain.connect(this.master);
      const len = this.ctx.sampleRate * 0.5; this.noiseBuf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
      const d = this.noiseBuf.getChannelData(0); for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
    } catch { this.ctx = null; }
  }

  setMuted(m: boolean) { this.muted = m; if (this.master && this.ctx) this.master.gain.setTargetAtTime(m ? 0 : 0.55, this.ctx.currentTime, 0.05); }

  private tone(f: number, dur: number, type: OscillatorType, vol: number, to?: number, delay = 0) {
    if (!this.ctx || !this.master) return;
    const t = this.ctx.currentTime + delay, o = this.ctx.createOscillator(), g = this.ctx.createGain();
    o.type = type; o.frequency.setValueAtTime(f, t); if (to) o.frequency.exponentialRampToValueAtTime(to, t + dur);
    g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(vol, t + 0.01); g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g); g.connect(this.master); o.start(t); o.stop(t + dur + 0.05);
  }
  private noise(dur: number, vol: number, freq: number, q = 1) {
    if (!this.ctx || !this.master || !this.noiseBuf) return;
    const t = this.ctx.currentTime, s = this.ctx.createBufferSource(), f = this.ctx.createBiquadFilter(), g = this.ctx.createGain();
    s.buffer = this.noiseBuf; f.type = 'bandpass'; f.frequency.value = freq; f.Q.value = q;
    g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    s.connect(f); f.connect(g); g.connect(this.master); s.start(t); s.stop(t + dur);
  }

  dig(hard: number) { this.noise(0.08, 0.25, 500 + hard * 400, 2); }
  breakBlock(hard: number) { this.noise(0.22, 0.45, 300 + hard * 500, 1.2); this.tone(140 + hard * 60, 0.12, 'triangle', 0.15, 70); }
  place() { this.noise(0.1, 0.35, 900, 3); this.tone(220, 0.08, 'square', 0.06, 180); }
  step() { this.noise(0.05, 0.08, 350, 1.5); }
  jump() { this.tone(260, 0.12, 'sine', 0.08, 420); }
  hit() { this.tone(180, 0.14, 'square', 0.12, 90); this.noise(0.1, 0.3, 1200, 2); }
  kill() { this.tone(520, 0.1, 'square', 0.1, 260); this.tone(330, 0.2, 'triangle', 0.12, 110, 0.06); }
  hurt() { this.tone(200, 0.25, 'sawtooth', 0.16, 70); }
  pickup() { this.tone(880, 0.08, 'sine', 0.12); this.tone(1320, 0.12, 'sine', 0.1, undefined, 0.07); }
  levelUp() { [523, 659, 784, 1046].forEach((f, i) => this.tone(f, 0.25, 'triangle', 0.14, undefined, i * 0.1)); }
  gameOver() { [392, 330, 262, 196].forEach((f, i) => this.tone(f, 0.4, 'triangle', 0.14, undefined, i * 0.18)); }

  /** Música ambiental: notas pentatónicas suaves al azar (llamar cada frame). */
  music(dt: number, night: boolean) {
    if (!this.ctx || !this.musicGain || this.muted) return;
    this.musicTimer -= dt; if (this.musicTimer > 0) return;
    this.musicTimer = 0.9 + Math.random() * 1.6;
    const scale = night ? [220, 261.6, 293.7, 329.6, 392, 440] : [261.6, 293.7, 329.6, 392, 440, 523.3];
    const f = scale[Math.floor(Math.random() * scale.length)] * (Math.random() < 0.3 ? 0.5 : 1);
    const t = this.ctx.currentTime, o = this.ctx.createOscillator(), g = this.ctx.createGain();
    o.type = 'sine'; o.frequency.value = f;
    g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(0.5, t + 0.08); g.gain.exponentialRampToValueAtTime(0.0001, t + 2.4);
    o.connect(g); g.connect(this.musicGain); o.start(t); o.stop(t + 2.5);
  }
}

export const sfx = new Sfx();

